describe('File Upload - Set Title and Description', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should successfully upload a file with title and description', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/files/upload').as('uploadFile');

    // Select file input
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-document.pdf', { force: true });

    // Fill title and description fields
    cy.get('[data-testid="file-title-input"]').type('Annual Report');
    cy.get('[data-testid="file-description-input"]').type('Yearly financial summary');

    // Submit the form
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@uploadFile');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify file details are displayed
    cy.get('[data-testid="file-details"]').should('be.visible');
    cy.get('[data-testid="file-title"]').should('contain', 'Annual Report');
    cy.get('[data-testid="file-description"]').should('contain', 'Yearly financial summary');

    // Verify file is listed in the uploads section
    cy.get('[data-testid="uploaded-files-list"]').should('contain', 'Annual Report');
  });

  it('should handle empty title and description fields', () => {
    // Intercept the file upload API
    cy.intercept('POST', '/api/files/upload').as('uploadFile');

    // Select file input
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample-document.pdf', { force: true });

    // Attempt to submit without filling title or description
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the API call
    cy.wait('@uploadFile');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Title and description are required');

    // Verify file is not listed in the uploads section
    cy.get('[data-testid="uploaded-files-list"]').should('not.contain', 'Annual Report');
  });
});
